# Manifest File: AI 项目的元数据描述
# package.json (Node) / pyproject.toml (Python) / Cargo.toml (Rust)

{
  "name": "my-app",
  "version": "1.0.0",
  "dependencies": {
    "@anthropic-ai/sdk": "^0.20.0",
    "next": "^14.0.0"
  },
  "scripts": {
    "test": "vitest run",
    "lint": "eslint .",
    "type-check": "tsc --noEmit"
  }
}

# AI 生成代码时必须：
# - 更新 manifest 添加新依赖
# - 跑 manifest 的 test/lint/type-check 命令
# - 检查 manifest 是否冲突

# Managed Settings: 团队 / 企业的 Claude Code 配置
# ~/.claude/settings.json (user-level)
# .claude/settings.json (project-level)
# .claude/settings.local.json (local, gitignored)

{
  "permissions": {
    "allow": ["Bash(npm test)", "Read(**/*.ts)"],
    "deny": ["Bash(rm -rf *)", "Bash(curl *)"]
  },
  "model": "claude-sonnet-4-5",
  "autoMode": "safe"
}

